const D = { energy:.6, scale:1, curvature:.55, hue:210, speed:1, density:.5, x:.5, y:.5, alpha:.85, fringe:.5, style:'lens', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const cx = P.x*width, cy = P.y*height;
const R = u * (0.6*P.scale);
const t = K.t;
const drift = 0.9*Math.sin(t*0.61) + 0.5*Math.sin(t*1.43+1.7) + 0.32*Math.sin(t*2.29);
const swell = (K.swell!=null ? K.swell : 0.5+0.5*Math.sin(t*0.4));
const kick = Math.max(0, K.pulse||0)*0.35 + (A.bass||0)*0.5;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };

// ---- style palettes (HSB) ----
const st = P.style;
let cGrid, cRim, cGlint, cPool, wire=false, fillPool=true;
if (st==='chrome'){ cGrid=[205,10,96]; cRim=[210,28,100]; cGlint=[45,6,100]; cPool=[210,22,64]; }
else if (st==='porthole'){ cGrid=[38,52,86]; cRim=[42,72,100]; cGlint=[48,22,100]; cPool=[32,58,54]; }
else if (st==='wire'){ cGrid=[P.hue,50,96]; cRim=[P.hue,58,100]; cGlint=[P.hue,18,100]; cPool=[P.hue,45,40]; wire=true; fillPool=false; }
else if (st==='sonar'){ cGrid=[138,78,80]; cRim=[138,88,100]; cGlint=[138,36,100]; cPool=[142,80,42]; }
else { cGrid=[P.hue,34,92]; cRim=[P.hue,42,100]; cGlint=[38,14,100]; cPool=[P.hue,46,58]; } // 'lens'

const k = 0.2 + 1.9*P.curvature;                 // barrel strength
const barrel = r => r*(1 + k*r*r)/(1 + k);       // radial map, normalized
const rot = t*0.045*P.speed + 0.25*drift;        // slow spin rate 1
const rot2 = t*0.019*P.speed + 1.3;              // rate 2 (incommensurate)
const cosr = Math.cos(rot), sinr = Math.sin(rot);
function warp(nx, ny){ const rx=nx*cosr-ny*sinr, ry=nx*sinr+ny*cosr; const r=Math.hypot(rx,ry)||1e-6; const f=barrel(Math.min(r,1.35))/r; return [cx+rx*f*R, cy+ry*f*R, r]; }

push();
// central refraction light pool (ADD)
if (fillPool){
  blendMode(ADD); noStroke();
  const pA = (14 + 30*P.energy) * (0.7 + 0.4*swell) * P.alpha;
  for (let g=7; g>=1; g--){
    const rr = R*0.98*(g/7);
    fill(cPool[0], cPool[1], cPool[2]*(0.45+0.09*g), pA*(g/7)*0.5);
    ellipse(cx, cy, rr*2, rr*2);
  }
}

// barrel-warped refraction grid (2-rate rotation via warp)
blendMode(ADD); noFill();
const nL = Math.round(7 + 12*P.density);         // lines each axis
strokeWeight(Math.max(1.1, u*0.0016));
const gA = (26 + 42*P.energy) * P.alpha;
const seg = 26;
for (let a=0; a<2; a++){                          // a=0 verticals, a=1 horizontals
  for (let i=0; i<=nL; i++){
    const c0 = -1 + 2*i/nL;
    if (Math.abs(c0) > 1.02) continue;
    stroke(cGrid[0], cGrid[1], cGrid[2], gA*(0.55+0.45*Math.sin(c0*3.1+t*0.3+i)));
    beginShape();
    for (let j=0; j<=seg; j++){
      const c1 = -1 + 2*j/seg;
      const nx = a===0 ? c0 : c1;
      const ny = a===0 ? c1 : c0;
      if (Math.hypot(nx,ny) > 1.18) { endShape(); beginShape(); continue; }
      const w = warp(nx, ny); vertex(w[0], w[1]);
    }
    endShape();
  }
}

// radial chromatic fringe rim (ADD, 3 offset rings) + specular glint
strokeWeight(Math.max(1.4, u*0.004));
const fr2 = P.fringe;
const rimA = (40 + 45*P.energy) * P.alpha * (0.75+0.35*swell);
noFill();
const rings = [[0, cRim[0]], [ -0.012*fr2, (cRim[0]+180)%360], [0.012*fr2, (cRim[0]+90)%360]];
for (const rg of rings){
  stroke(rg[1], 60*(0.4+0.6*fr2)+20, 100, rimA*0.8);
  ellipse(cx, cy, 2*R*(1+rg[0]), 2*R*(1+rg[0]));
}
// bright inner rim
stroke(cRim[0], cRim[1], cRim[2], rimA);
ellipse(cx, cy, 2*R*0.985, 2*R*0.985);

// orbiting specular glint (moving hotspot = symmetry break)
blendMode(ADD); noStroke();
const ga = rot2*2.0;
const gx = cx + Math.cos(ga)*R*0.66, gy = cy + Math.sin(ga)*R*0.66*0.9;
const gsz = u*(0.05 + 0.08*P.energy)*(1+0.5*kick);
drawingContext.shadowBlur = gsz*0.9; drawingContext.shadowColor = 'rgba(255,255,255,0.5)';
fill(cGlint[0], cGlint[1], cGlint[2], (70+25*P.energy)*P.alpha);
ellipse(gx, gy, gsz, gsz);
fill(cGlint[0], cGlint[1]*0.4, 100, (60)*P.alpha);
ellipse(gx, gy, gsz*0.45, gsz*0.45);
drawingContext.shadowBlur = 0;

// soft dark ring just outside the lens (BLEND) so the sphere reads as glass
blendMode(BLEND); noFill();
const vA = (24 + 30*P.energy) * P.alpha;
for (let g=1; g<=3; g++){
  stroke(230, 45, 5, vA*(4-g)/3*0.5);
  strokeWeight(u*0.02*g);
  ellipse(cx, cy, 2*R*(1.03+0.03*g), 2*R*(1.03+0.03*g));
}
noStroke();
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
